/* Mahalanobis 이상탐지기 (정상 데이터만으로 학습됨, 8개 피처) */
static const double MAHA_MEAN[8] = {0.0946096554, 12.7730369568, 0.0000000000, 1.9080319405, 49.6554718018, 115.3551025391, 1.0553877354, 0.3392829299};
static const double MAHA_INV_COV[64] = {367.4645618210, 1.5463873925, -0.0000000000, -3.3956672788, 0.0514753790, 0.0000021352, -0.1484271905, 0.2890636819, 1.5463873925, 0.2090760325, 0.0000000000, -0.0326817447, 0.0006009238, -0.0000006255, 0.0222117574, -0.0345988659, 0.0000000000, 0.0000000000, 1000000.0000000000, 0.0000000000, 0.0000000000, 0.0000000000, 0.0000000000, 0.0000000000, -3.3956672788, -0.0326817447, -0.0000000000, 3.5704552561, -0.0722338332, 0.0000018784, -0.5796259756, 2.7072577725, 0.0514753790, 0.0006009238, 0.0000000000, -0.0722338332, 0.0025853677, -0.0000000203, 0.0036910054, -0.0677726684, 0.0000021352, -0.0000006255, 0.0000000000, 0.0000018784, -0.0000000203, 0.0000000087, 0.0000005618, -0.0000019283, -0.1484271905, 0.0222117574, 0.0000000000, -0.5796259756, 0.0036910054, 0.0000005618, 1.2137399426, 0.0405369167, 0.2890636819, -0.0345988659, 0.0000000000, 2.7072577725, -0.0677726684, -0.0000019283, 0.0405369167, 33.1214387144};
static const double MAHA_THRESHOLD = 11.1400785529;

/* 0=정상, 1=이상(미지 공격 가능성) 반환 */
int maha_predict(double *x) {
    double diff[8];
    for (int i = 0; i < 8; i++) diff[i] = x[i] - MAHA_MEAN[i];
    double dist2 = 0.0;
    for (int i = 0; i < 8; i++) {
        double s = 0.0;
        for (int j = 0; j < 8; j++) s += MAHA_INV_COV[i * 8 + j] * diff[j];
        dist2 += diff[i] * s;
    }
    double dist = sqrt(dist2);
    return dist > MAHA_THRESHOLD ? 1 : 0;
}

/* ===== 통합 판정 함수 =====
   x: 피처 배열 [freq_in_window, unique_ids_in_window, is_unknown_id,
                 entropy, mean_byte, delta_zscore, value_zscore, norm_id]
   반환: 0=R(정상), 1=DoS, 2=Fuzzy, 3=RPM, 4=gear, 5=미지의 이상패턴(Zero-day)
*/
int can_ids_predict(double *x) {
    double scores[5];
    score(x, scores);  /* m2cgen이 생성한 LightGBM 함수 */
    int best = 0;
    for (int i = 1; i < 5; i++) if (scores[i] > scores[best]) best = i;
    if (best != 0) return best;          /* 알려진 공격으로 분류됨 */
    if (maha_predict(x)) return 5;       /* 알려진 패턴은 아니지만 통계적으로 이상함 (Zero-day) */
    return 0;                            /* 정상 */
}
